import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Providers and keys","description":"","frontmatter":{},"headers":[],"relativePath":"guide/providers.md","filePath":"guide/providers.md","lastUpdated":1793458229000}'),s={name:"guide/providers.md"};function a(i,e,d,l,c,g){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="providers-and-keys" tabindex="-1">Providers and keys <a class="header-anchor" href="#providers-and-keys" aria-label="Permalink to &quot;Providers and keys&quot;">​</a></h1><p>This page describes each supported provider: where to get a key, where to enter it, how to check it, and the errors you&#39;re most likely to see.</p><p>All keys are stored only in Windows Credential Manager, in entries named <code>MeetCue</code>. They are never written to the settings file or the logs, and the interface only knows whether a key is configured.</p><p>Choose the provider and type the model name for each task in <strong>Settings › Providers &amp; cost › Providers &amp; models</strong>. MeetCue doesn&#39;t list models or prices: once a key is saved, the names the provider reports appear as suggestions, and each provider has an <strong>Official pricing</strong> link to its own price page.</p><h2 id="soniox" tabindex="-1">Soniox <a class="header-anchor" href="#soniox" aria-label="Permalink to &quot;Soniox&quot;">​</a></h2><p>Speech recognition that handles Chinese and English mixed in one sentence, with built-in sentence-end detection. Billed per hour of audio.</p><ol><li><strong>Get a key</strong>: sign in to the Soniox console and create an API key.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › Addresses &amp; keys › Soniox key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification lists the real-time models available to your account.</li><li><strong>Endpoint</strong>: Soniox runs several endpoints. Keep <strong>Auto</strong> and run the <a href="/meetcue/guide/latency">latency probe</a> to choose the fastest.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a> (key rejected), <a href="/meetcue/troubleshooting/error-codes#mc-asr-002">MC-ASR-002</a> (can&#39;t connect).</p><h2 id="deepgram" tabindex="-1">Deepgram <a class="header-anchor" href="#deepgram" aria-label="Permalink to &quot;Deepgram&quot;">​</a></h2><p>Streaming speech recognition, billed per minute of audio.</p><ol><li><strong>Get a key</strong>: sign in to the Deepgram console, open your project and create an API key with member permissions.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › Addresses &amp; keys › Deepgram key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification lists your projects and the available speech models.</li><li><strong>Languages</strong>: set <strong>Settings › Audio › Meeting languages</strong>, main language first. Deepgram can&#39;t recognise Chinese and English in the same stream, so with both selected it recognises only the main one; for meetings that mix them, Soniox works better.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a>, <a href="/meetcue/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a> (rate limited).</p><h2 id="alibaba-cloud" tabindex="-1">Alibaba Cloud (Fun-ASR) <a class="header-anchor" href="#alibaba-cloud" aria-label="Permalink to &quot;Alibaba Cloud (Fun-ASR) {#alibaba-cloud}&quot;">​</a></h2><p>Alibaba Cloud Model Studio&#39;s real-time recognition, built for Mandarin with English terms mixed in and several dialects. Billed per second of audio.</p><ol><li><strong>Get a key</strong>: in the Model Studio console, choose the region at the top (Singapore for use outside the Chinese mainland, Beijing inside it) and create an API key there. Keys work only in the region that created them.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › Addresses &amp; keys › Alibaba Cloud (Fun-ASR) key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification starts and ends an empty recognition task, so it uses no audio.</li><li><strong>Endpoint</strong>: MeetCue knows both regions&#39; addresses. If the chosen one rejects the key, it tries the other region and keeps using the one that works.</li><li><strong>Model</strong>: <code>fun-asr-realtime</code> (default) uses your hotwords as context. <code>paraformer-realtime-v2</code> is available only in Beijing.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a> (key rejected in both regions), <a href="/meetcue/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a> (rate limited or account in arrears).</p><h2 id="tencent-cloud" tabindex="-1">Tencent Cloud ASR <a class="header-anchor" href="#tencent-cloud" aria-label="Permalink to &quot;Tencent Cloud ASR {#tencent-cloud}&quot;">​</a></h2><p>Tencent Cloud&#39;s real-time recognition, with Mandarin, English, Cantonese and many dialects. Billed per hour of audio.</p><ol><li><strong>Get a key</strong>: activate speech recognition in the Tencent Cloud console, then open <strong>Access management › API keys</strong>. You need your <strong>AppID</strong> (shown on the same page and in account info), a <strong>SecretId</strong> and its <strong>SecretKey</strong>.</li><li><strong>Enter it</strong>: in <strong>Settings › Providers &amp; cost › Addresses &amp; keys › Tencent Cloud ASR key</strong>, paste all three as <code>AppID:SecretId:SecretKey</code>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification opens a signed connection and closes it without sending audio.</li><li><strong>Model</strong>: <code>16k_zh_en</code> (default) recognises Chinese and English in one sentence plus 31 dialects. <code>16k_zh</code> is the cheaper standard Mandarin model, <code>16k_yue</code> is Cantonese and <code>16k_en</code> is English.</li><li><strong>Outside the Chinese mainland</strong>: a Chinese-site account may be refused from abroad. MeetCue reports this as a key error with Tencent&#39;s message; use an account on the international site instead.</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-asr-001">MC-ASR-001</a> (signature rejected, service not activated, or overseas access), <a href="/meetcue/troubleshooting/error-codes#mc-asr-003">MC-ASR-003</a> (resource pack used up, arrears or too many streams).</p><h2 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h2><p>Claude models for question detection and hints.</p><ol><li><strong>Get a key</strong>: sign in to the Claude Console, open <strong>API keys</strong> and create a key. Add credit or a payment method to the organization.</li><li><strong>Enter it</strong>: <strong>Settings › Providers &amp; cost › Addresses &amp; keys › Anthropic key</strong>, then <strong>Save and verify</strong>.</li><li><strong>Check</strong>: verification loads the model list from the API; its names appear as suggestions in the <strong>Model</strong> field. You can also type any other model name.</li><li><strong>Base URL</strong> (optional): leave it empty to use <code>https://api.anthropic.com</code>. To go through a gateway or proxy that speaks the Messages API, enter its address, for example <code>https://gateway.example.com</code> (MeetCue adds <code>/v1</code> if it&#39;s missing).</li></ol><p>Common errors: <a href="/meetcue/troubleshooting/error-codes#mc-llm-002">MC-LLM-002</a> (key rejected), <a href="/meetcue/troubleshooting/error-codes#mc-llm-003">MC-LLM-003</a> (rate limited), <a href="/meetcue/troubleshooting/error-codes#mc-llm-004">MC-LLM-004</a> (model not available).</p><h2 id="openai-compatible-apis" tabindex="-1">OpenAI-compatible APIs <a class="header-anchor" href="#openai-compatible-apis" aria-label="Permalink to &quot;OpenAI-compatible APIs&quot;">​</a></h2><p>Any service that implements the OpenAI chat completions API with streaming, including self-hosted model servers.</p><ol><li><strong>Base URL</strong>: choose <strong>OpenAI-compatible</strong> for a task, then in <strong>Settings › Providers &amp; cost › Addresses &amp; keys</strong> enter the base URL ending in <code>/v1</code>, for example <code>https://llm.example.com/v1</code>.</li><li><strong>Key</strong>: paste the service&#39;s API key under <strong>OpenAI-compatible key</strong>. Leave it empty if the service doesn&#39;t need one.</li><li><strong>Check</strong>: <strong>Save and verify</strong> loads <code>/v1/models</code>, whose names appear as suggestions in the <strong>Model</strong> field. Type the model name your service uses.</li><li><strong>Price</strong>: for cost estimates and budgets, enter the service&#39;s price under <strong>Settings › Providers &amp; cost › Budget › Your own prices</strong>.</li></ol><p>Some services don&#39;t report token usage while streaming. Usage and cost then show as zero for them.</p><h2 id="corporate-networks" tabindex="-1">Corporate networks <a class="header-anchor" href="#corporate-networks" aria-label="Permalink to &quot;Corporate networks&quot;">​</a></h2><p>MeetCue uses the Windows certificate store, so certificates installed by your company are trusted. It follows the manual proxy set in Windows Settings (<strong>Network &amp; internet › Proxy</strong>) for all connections, including speech recognition. Automatic configuration scripts are not evaluated; if your network uses one, or to use a different proxy, enter it in <strong>Settings › Providers &amp; cost › Advanced › HTTPS proxy</strong>. If connections fail with <a href="/meetcue/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>, see <a href="/meetcue/troubleshooting/latency#company-network">High latency</a>.</p>',30)])])}const m=o(s,[["render",a]]);export{p as __pageData,m as default};
